// Regenerates files derived from package.json and src/settings.ts.
// `--check` fails instead of writing, for CI.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { xcconfig } from '../src/settings.ts';

const check = process.argv.includes('--check');
const pkg = JSON.parse(readFileSync('package.json', 'utf8')) as { version: string };

const files: Record<string, string> = {
	'src/version.ts': `// Generated by scripts/gen.ts from package.json. Do not edit.\nexport const VERSION = '${pkg.version}';\n`,
	'xcconfig/reproducible.xcconfig': xcconfig(),
};

let stale = 0;
for (const [path, content] of Object.entries(files)) {
	let current: string | undefined;
	try {
		current = readFileSync(path, 'utf8');
	} catch {}
	if (current === content) continue;
	if (check) {
		console.error(`${path} is out of date; run \`npm run gen\``);
		stale++;
	} else {
		mkdirSync(path.split('/').slice(0, -1).join('/'), { recursive: true });
		writeFileSync(path, content);
		console.log(`wrote ${path}`);
	}
}
process.exitCode = stale ? 1 : 0;
